import test from 'node:test';
import assert from 'node:assert/strict';
import {
  NATIVE_WASM_REQUEST_SCHEMA as REQUEST,
  NATIVE_WASM_RESPONSE_SCHEMA as RESPONSE,
  NATIVE_WASM_ACK_SCHEMA as ACK,
  NATIVE_WASM_DATA_MAX_BYTES as LIMIT,
  encodeNativeWasmDataV0, decodeNativeWasmDataV0
} from '../src/native-wasm-data-v0.mjs';

// Golden bytes generated independently from source.wasm's canonical
// MessagePack wire contract: [2, schemaId, bin8(sha256(shape)), [ticket,i64]].
// These constants must not be generated by the implementation under test.
const golden = [
  [REQUEST, 1n, 42n,
   '9402d9246f7265736c616e672e6e61746976655f7761736d2e646174612e726571756573742e7630c4201ef812fd0d886c973c520cd707ded5ca4593a81414b5c3aa77b1b0c147c4871892012a'],
  [RESPONSE, 19n, -42n,
   '9402d9256f7265736c616e672e6e61746976655f7761736d2e646174612e726573706f6e73652e7630c4201ef812fd0d886c973c520cd707ded5ca4593a81414b5c3aa77b1b0c147c487189213d0d6'],
  [ACK, 9223372036854775807n, -9223372036854775808n,
   '9402d9206f7265736c616e672e6e61746976655f7761736d2e646174612e61636b2e7630c4201ef812fd0d886c973c520cd707ded5ca4593a81414b5c3aa77b1b0c147c4871892cf7fffffffffffffffd38000000000000000']
];

test('browser adapter emits byte-exact WASM/native DATA v0 frames', async () => {
  for (const [schema, ticket, value, hex] of golden) {
    const encoded = await encodeNativeWasmDataV0(schema, ticket, value);
    assert.equal(Buffer.from(encoded).toString('hex'), hex, schema);
    const parsed = await decodeNativeWasmDataV0(schema, encoded);
    assert.deepEqual(parsed, {ticket, value});
    assert.equal(Object.isFrozen(parsed), true);
  }
});

test('DATA adapter never accepts CONTROL, wrong schema or out-of-range tickets', async () => {
  await assert.rejects(encodeNativeWasmDataV0('CONTROL', 1n, 1n), /unregistered/);
  await assert.rejects(encodeNativeWasmDataV0(REQUEST, 0n, 1n), /positive/);
  await assert.rejects(encodeNativeWasmDataV0(REQUEST, 1, 1n), /signed i64/);
  await assert.rejects(encodeNativeWasmDataV0(REQUEST, 1n, 1), /signed i64/);
  await assert.rejects(encodeNativeWasmDataV0(REQUEST, 1n, 9223372036854775808n), /signed i64/);
  const encoded = await encodeNativeWasmDataV0(REQUEST, 1n, 42n);
  await assert.rejects(decodeNativeWasmDataV0(RESPONSE, encoded), /schema ID mismatch/);
  const zero = Uint8Array.from(encoded);
  zero[zero.length - 2] = 0;
  zero[zero.length - 1] = 0;
  await assert.rejects(decodeNativeWasmDataV0(REQUEST, zero), /trailing|tuple|version|noncanonical/);
});

test('native DATA adapter rejects shared and forged input without probing a Proxy', async () => {
  const encoded = await encodeNativeWasmDataV0(REQUEST, 19n, -42n);
  const shared = new Uint8Array(new SharedArrayBuffer(encoded.length));
  shared.set(encoded);
  await assert.rejects(decodeNativeWasmDataV0(REQUEST, shared), /shared memory/);
  let getterCalls = 0;
  const forged = new Proxy(encoded, {get() {getterCalls++; throw Error('forged getter');}});
  await assert.rejects(decodeNativeWasmDataV0(REQUEST, forged), /expected nonshared binary/);
  assert.equal(getterCalls, 0);
  const oversized = new Uint8Array(LIMIT + 1);
  await assert.rejects(decodeNativeWasmDataV0(REQUEST, oversized), /frame byte budget/);
});

test('decode snapshots before awaited digest; producer mutation cannot change result', async () => {
  const encoded = await encodeNativeWasmDataV0(REQUEST, 5n, 127n);
  const result = decodeNativeWasmDataV0(REQUEST, encoded);
  encoded.fill(0);
  assert.deepEqual(await result, {ticket: 5n, value: 127n});
});
